function drawEditorRoadGrid(r){
 if(!editorTesting||r<z-1||r>z+30)return;
 ctx.save();ctx.lineWidth=1;ctx.globalAlpha=Math.max(.2,1-(r-z)/38);
 for(let l=0;l<7;l++){
  const a=l-roadOffset(),points=[proj(a,r,.005),proj(a+1,r,.005),proj(a+1,r+1,.005),proj(a,r+1,.005)],gap=!rows[r]?.[l];
  ctx.strokeStyle=r===2&&l===3?'#ffe28b':gap?'#72cad099':'#e6f8efbb';ctx.setLineDash(gap?[3,4]:[]);
  ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<4;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.stroke();
  if(r===2&&l===3){const p=proj(0,2.5,.01);ctx.setLineDash([]);ctx.fillStyle='#ffe28b';ctx.font='bold 12px sans-serif';ctx.textAlign='center';ctx.fillText('START',p[0],p[1]);}
 }
 ctx.setLineDash([]);
 if(r>=z&&r<z+18){const p=proj(-3.65,r+.5,.01);ctx.font='bold '+Math.max(8,Math.min(13,p[2]*.22))+'px sans-serif';ctx.fillStyle='#e6f8ef';ctx.textAlign='right';ctx.fillText((r+1)+'줄',p[0],p[1]);}
 ctx.restore();
}
const editorGridDraw=draw;draw=function(){editorGridDraw();if(editorTesting){const lane=Math.floor(x+roadOffset());$('segment').textContent='에디터 '+(Math.floor(z)+1)+'줄 · '+(lane>=0&&lane<7?(lane+1)+'칸':'도로 밖')+' / 총 '+rows.length+'줄';}};

