function tr(source){if(settings.language==='ko')return source;const n={en:0,ja:1,zh:2}[settings.language];if(uiWords[source])return uiWords[source][n];return source;}
function translateDynamic(text){
 let s=tr(text);if(s!==text||settings.language==='ko')return s;
 const n={en:0,ja:1,zh:2}[settings.language];
 const tokens={'단계 · 중력 ':[' · Gravity ','段階 · 重力 ','层 · 重力 '],' · 착지 후 ':[' · on landing ',' · 着地後 ',' · 着陆后 '],'m · 획득 ':['m · earned ','m · 獲得 ','m · 获得 '],' · 제한 ':[' · Limit ',' · 制限 ',' · 限时 '],'코스 ':['Course ','コース ','关卡 '],' 시작 →':[' Start →',' 開始 →',' 开始 →'],'최단 ':['Best ','最短 ','最快 '],'이번 ':['This run ','今回 ','本次 '],'신기록!':['New best!','新記録！','新纪录！'],'항로 난도 ':['Course difficulty ','航路難度 ','航线难度 '],'무한 항로 · ':['Endless · ','無限航路 · ','无尽航线 · '],'보유 코인 ':['Coins ','所持コイン ','持有金币 '],'이 브라우저에 자동 저장':['Saved in this browser','このブラウザーに自動保存','自动保存在本浏览器中'],'최고 ':['Best ','最高 ','最高 '],' 클리어':[' cleared',' クリア',' 已完成'],' 코인':[' coins',' コイン',' 金币'],' · 신기록':[' · New best',' · 新記録',' · 新纪录']};
 for(const key of Object.keys(uiWords).filter(k=>k.length>=5).sort((a,b)=>b.length-a.length))s=s.split(key).join(uiWords[key][n]);
 for(const key of Object.keys(tokens).sort((a,b)=>b.length-a.length))s=s.split(key).join(tokens[key][n]);
 s=s.replace(/(\d+(?:\.\d+)?)초/g,'$1'+['s','秒','秒'][n]);
 return s;
}
const localizedText=new WeakMap();
function localizeUI(){
 if(document.documentElement)document.documentElement.lang=settings.language==='zh'?'zh-CN':settings.language;
 if(!document.createTreeWalker)return;
 for(const root of [document.getElementById('overlay'),document.getElementById('mapEditor'),document.querySelector('header'),document.querySelector('.cockpit'),$('note'),$('segment'),document.querySelector('.flight-strip')]){
  if(!root||root.classList?.contains?.('hidden'))continue;const walker=document.createTreeWalker(root,4);let node;
  while((node=walker.nextNode())){if(node.parentElement?.closest?.('[data-l10n-skip]'))continue;const current=node.nodeValue,old=localizedText.get(node);if(old&&old.translated===current&&old.language===settings.language)continue;const original=old&&old.translated===current?old.original:current;const trimmed=original.trim();const translated=trimmed?original.replace(trimmed,translateDynamic(trimmed)):original;localizedText.set(node,{original,translated,language:settings.language});if(current!==translated)node.nodeValue=translated;}
 }
}
