let stickPointer=null;
function releaseAnalog(){stickPointer=null;steeringAxis=0;$('analogKnob').style.transform='translate(-50%,-50%)';$('analogStick').setAttribute('aria-valuenow','0');$('analogStick').setAttribute('data-direction','neutral');}
const commandReset=resetJoystick;resetJoystick=function(){releaseAnalog();return commandReset()};
function moveAnalog(e){const rect=$('analogStick').getBoundingClientRect();const knob=$('analogKnob').getBoundingClientRect();const knobWidth=knob.width>0&&knob.width<rect.width?knob.width:Math.min(56,rect.width*.44);const radius=Math.max(1,(rect.width-knobWidth)/2-10);const dx=Math.max(-radius,Math.min(radius,e.clientX-(rect.left+rect.width/2)));const axis=dx/radius;steeringAxis=Math.abs(axis)<.12?0:Math.sign(axis)*(Math.abs(axis)-.12)/.88;$('analogKnob').style.transform='translate(calc(-50% + '+dx+'px),-50%)';$('analogStick').setAttribute('aria-valuenow',String(Math.round(steeringAxis*100)));$('analogStick').setAttribute('data-direction',steeringAxis<0?'left':steeringAxis>0?'right':'neutral');}
$('analogStick').addEventListener('pointerdown',e=>{if(settings.controls!=='joystick'||!['ready','play'].includes(state)||stickPointer!==null||(e.button!==undefined&&e.button!==0))return;e.preventDefault();stickPointer=e.pointerId;$('analogStick').setPointerCapture(e.pointerId);moveAnalog(e)});
$('analogStick').addEventListener('pointermove',e=>{if(e.pointerId===stickPointer){e.preventDefault();moveAnalog(e)}});
for(const name of ['pointerup','pointercancel','lostpointercapture'])$('analogStick').addEventListener(name,e=>{if(e.pointerId===stickPointer){e.preventDefault();releaseAnalog()}});
for(const name of ['contextmenu','selectstart','dragstart'])$('analogStick').addEventListener(name,e=>e.preventDefault());
$('analogStick').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();steeringAxis=e.key==='ArrowLeft'?-1:1;}});
$('analogStick').addEventListener('keyup',releaseAnalog);$('analogStick').addEventListener('blur',releaseAnalog);
if(typeof MutationObserver!=='undefined'){let localizing=false;const observer=new MutationObserver(()=>{if(localizing)return;localizing=true;localizeUI();observer.takeRecords();localizing=false});observer.observe(document.body,{subtree:true,childList:true,characterData:true});}

