// Elapsed flight time shares the exact clock used for story clear records.
function syncRunClock(){
 const endless=mode==='endless',value=endless?String(displayDistance(flightDistance())):Math.max(0,Number.isFinite(time)?time:0).toFixed(2);
 if($('runClock').textContent!==value)$('runClock').textContent=value;
 $('courseLabel').textContent=tr('항로');
 $('clockLabel').textContent=endless?({ko:'거리',en:'Distance',ja:'距離',zh:'距离'})[settings.language]:({ko:'시간',en:'Time',ja:'時間',zh:'时间'})[settings.language];
 $('clockUnit').textContent=endless?'m':settings.language==='en'?'s':settings.language==='ko'?'초':'秒';
 $('runMetric').setAttribute('role',endless?'group':'timer');
 $('ghostToggle').setAttribute('data-endless',String(endless));
}

const clockDraw=draw;draw=function(){clockDraw();syncRunClock()};
const clockBegin=beginRun;beginRun=function(...args){const result=clockBegin(...args);syncRunClock();return result};start=beginRun;
syncRunClock();

